// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon, CrosshairIcon } from 'lucide-react'

import {
  BrowserChrome,
  DemoStage,
  DockHeader,
  mockImage,
  type Build,
} from '@/app/demos/stage'

import { CAPTIONS, PATH, PLAYWRIGHT, SELECTORS } from './script'

const RELATIVE = 2

const build: Build = ({ tl, q, qa, pos, step, final, move, click, type, wait, cursorOut }) => {
  step(0)
  move('pick')
  click('pick')
  const target = pos('target', 0, 0)
  move('target', { at: '+=0.1' })
  tl.fromTo(
    q('ov'),
    { x: target.x, y: target.y, width: target.w, height: target.h, opacity: 0 },
    { opacity: 1, duration: 0.25, immediateRender: false },
    '<0.3',
  )
  click('target')

  step(1, '+=0.3')
  qa('seg').forEach((segment, index) => {
    tl.to(
      segment,
      {
        backgroundColor: 'rgba(45,212,191,0.22)',
        color: '#5eead4',
        borderColor: 'rgba(45,212,191,0.6)',
        duration: 0.2,
      },
      index === 0 ? '<' : '>',
    )
    tl.to(q(`node-${index}`), { outlineColor: 'rgba(45,212,191,0.7)', duration: 0.2 }, '<')
    type(`sel-${RELATIVE}`, PATH.slice(0, index + 1).join(' > '), { at: '<', speed: 0.03 })
  })

  step(2, '+=0.4')
  SELECTORS.forEach((selector, index) => {
    if (index === RELATIVE) return
    type(`sel-${index}`, selector.value, { at: index === 0 ? '>' : '<0.12', speed: 0.009 })
  })
  tl.fromTo(
    q('first'),
    { opacity: 0, scale: 0.8 },
    { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(2.5)' },
  )

  step(3, '+=0.4')
  move('copy-0')
  click('copy-0')
  tl.to(q('copy-0'), { color: '#2dd4bf', duration: 0.15 }, '<')
  tl.fromTo(
    q('spec'),
    { opacity: 0, y: 14 },
    { opacity: 1, y: 0, duration: 0.4, ease: 'power3.out' },
    '+=0.1',
  )
  type('spec-line', PLAYWRIGHT, { speed: 0.012 })
  cursorOut('+=0.2')
  tl.set(qa('seg'), { clearProps: 'color,backgroundColor,borderColor' })
  ;['node-0', 'node-1', 'node-2', 'node-3'].forEach((name) =>
    tl.set(q(name), { clearProps: 'outlineColor' }),
  )
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Selector Generator building CSS and XPath selectors for an Add to cart button"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://shop.northwind.app/lamps"
        panelWidth={262}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="flex min-h-0 flex-1 flex-col gap-1.5 p-2.5">
              <span
                data-d="pick"
                className="flex h-7 w-fit items-center gap-1.5 rounded-lg bg-[var(--accent)] px-2.5 text-[10px] font-medium text-canvas"
              >
                <CrosshairIcon className="size-3" /> Pick element on page
              </span>
              {SELECTORS.map((selector, index) => (
                <div
                  key={selector.label}
                  className="flex h-[34px] items-center gap-1.5 rounded-lg border border-line bg-canvas/60 px-2"
                >
                  <div className="min-w-0 flex-1">
                    <p className="flex items-center gap-1 text-[8.5px] font-medium text-muted">
                      {selector.label}
                      {index === 0 ? (
                        <span
                          data-d="first"
                          className="rounded-full bg-[var(--accent)]/20 px-1.5 text-[7.5px] text-[var(--accent)] opacity-0"
                        >
                          test attribute
                        </span>
                      ) : null}
                    </p>
                    <p
                      data-d={`sel-${index}`}
                      className="h-[13px] truncate font-mono text-[9px] text-ink"
                    />
                  </div>
                  <span
                    data-d={`copy-${index}`}
                    className="flex size-4 items-center justify-center text-muted"
                  >
                    <CopyIcon className="size-2.5" />
                  </span>
                </div>
              ))}
            </div>
          </div>
        }
      >
        <div className="flex h-full flex-col bg-[#fafafa] text-[#111]">
          <div
            data-d="node-0"
            className="m-2 flex-1 rounded-md outline outline-1 outline-offset-2 outline-transparent"
          >
            <p className="px-2 pt-1.5 text-[12px] font-bold tracking-tight">Lamps</p>
            <div
              data-d="node-1"
              className="mx-2 mt-1.5 grid grid-cols-2 gap-2 rounded-md outline outline-1 outline-offset-2 outline-transparent"
            >
              {['Aero Lamp', 'Arc Lamp'].map((name, index) => (
                <div
                  key={name}
                  data-d={index === 0 ? 'node-2' : undefined}
                  className="rounded-lg bg-white p-1.5 shadow-sm outline outline-1 outline-offset-1 outline-transparent"
                >
                  <div className="h-14 rounded-md" style={{ background: mockImage(index + 2) }} />
                  <p className="mt-1 text-[8.5px] font-medium">{name}</p>
                  <p className="text-[8.5px] text-[#7c3aed]">${[89, 129][index]}</p>
                  <span
                    data-d={index === 0 ? 'target node-3' : undefined}
                    className="mt-1 block rounded-md bg-[#111] py-1 text-center text-[8.5px] text-white outline outline-1 outline-offset-1 outline-transparent"
                  >
                    Add to cart
                  </span>
                </div>
              ))}
            </div>
          </div>
          <div className="flex flex-wrap gap-1 border-t border-black/10 bg-white px-2 py-1.5 font-mono text-[8.5px]">
            {PATH.map((segment) => (
              <span
                key={segment}
                data-d="seg"
                className="rounded border border-black/10 px-1 text-[#555]"
              >
                {segment}
              </span>
            ))}
          </div>
        </div>
        <div
          data-d="spec"
          className="absolute inset-x-2 bottom-10 rounded-lg border border-white/10 bg-[#0f172a] p-2 font-mono text-[8.5px] text-[#e2e8f0] opacity-0 shadow-xl"
        >
          <p className="mb-1 text-[8px] text-[#94a3b8]">cart.spec.ts</p>
          <p data-d="spec-line" className="break-all" />
        </div>
      </BrowserChrome>
      <div
        data-d="ov"
        className="pointer-events-none absolute left-0 top-0 z-30 size-2 rounded-[2px] border-2 border-[#6366f1] bg-[rgba(99,102,241,0.12)] opacity-0"
      />
    </DemoStage>
  )
}
